fn main() {
    let s = "uu\u{308}u";
    let chars: String = s.chars().rev().collect();
    println!("orig   = {} ({} bytes)", s, s.len());
    println!("chars  = {}  <-- {} codepoints", chars, chars.chars().count());
    println!("equal? {}", s == chars);
    for c in s.chars() { println!("  U+{:04X}", c as u32); }
}
